{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "Ensure ALB protocol is HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The load balancer listener is configured to use HTTP on port 80, which transmits data in cleartext and exposes it to interception or tampering. It should be configured to use HTTPS with a valid SSL/TLS certificate."
    }
  ],
  "patched_code": "resource "aws_lb_listener" "webserver_listner" {
  load_balancer_arn = aws_lb.levelup-load-balancer.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"
  certificate_arn   = var.acm_certificate_arn # User must provide a valid ACM certificate ARN

  default_action {
    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn
    type             = "forward"
  }
}

variable "acm_certificate_arn" {
  description = "ARN of the ACM certificate for the HTTPS listener"
  type        = string
}",
  "fix_summary": "Changed the listener protocol from HTTP to HTTPS, updated the port to 443, added an SSL policy, and introduced a variable for the required ACM certificate ARN to enforce encrypted traffic."
}
